import { library } from '@fortawesome/fontawesome-svg-core';
import { faBars, faPhone, faArrowRight } from '@fortawesome/free-solid-svg-icons';
// import { fa} from '@fortawesome/free-regular-svg-icons';
import { faFacebook, faTwitter, faLinkedin, faDribbble, faBehance } from '@fortawesome/free-brands-svg-icons';

// Add the icons to the library
library.add(faBars, faPhone, faFacebook, faTwitter, faLinkedin, faArrowRight, faDribbble, faBehance);

export default library;
